"""Bundled HTML interface resources for Android and frozen desktop builds."""
from pathlib import Path

FILES = {
"index.html": "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"color-scheme\" content=\"dark\">\n  <title>ProtoBot</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n  <script defer src=\"app.js\"></script>\n</head>\n<body>\n  <div class=\"app-shell\">\n    <aside class=\"sidebar\">\n      <div class=\"brand\">\n        <div class=\"brand-mark\">P</div>\n        <div><strong>ProtoBot</strong><small>Minecraft AI</small></div>\n      </div>\n      <nav class=\"nav\">\n        <button class=\"nav-item active\" data-section=\"dashboard\"><span class=\"nav-icon\">⌂</span> Visão geral</button>\n        <button class=\"nav-item\" data-section=\"settings\"><span class=\"nav-icon\">⚙</span> Configurações</button>\n        <button class=\"nav-item\" data-section=\"console\"><span class=\"nav-icon\">⌘</span> Console</button>\n      </nav>\n      <div class=\"sidebar-footer\">\n        <span class=\"connection-dot\" id=\"sideDot\"></span>\n        <span id=\"sideStatus\">Bot desconectado</span>\n      </div>\n    </aside>\n\n    <main class=\"main\">\n      <header class=\"topbar\">\n        <div><span class=\"eyebrow\">MINECRAFT JAVA EDITION</span><h1 id=\"pageTitle\">Visão geral</h1></div>\n        <div class=\"top-status\"><span class=\"status-dot\" id=\"statusDot\"></span><span id=\"statusText\">Parado</span></div>\n      </header>\n\n      <section class=\"page active\" id=\"page-dashboard\">\n        <div class=\"welcome-card\">\n          <div>\n            <span class=\"eyebrow\">ASSISTENTE AUTÔNOMO</span>\n            <h2>Seu bot, pronto para explorar.</h2>\n            <p>Configure a conexão, inicie o ProtoBot e acompanhe as atividades em tempo real.</p>\n          </div>\n          <div class=\"welcome-orb\">P</div>\n        </div>\n\n        <aside class=\"compatibility-notice\" role=\"note\">\n          <strong>Compatibilidade: somente Minecraft Java Edition</strong>\n          <p>O ProtoBot se conecta a servidores Java. Para jogar pelo Bedrock, o servidor Java precisa aceitar conexões Bedrock por meio do <a href=\"https://geysermc.org/\" target=\"_blank\" rel=\"noopener noreferrer\">GeyserMC</a>.</p>\n          <p><strong>Floodgate:</strong> não é obrigatório em todos os casos. Em servidores Java com <code>online-mode=true</code>, use Floodgate se quiser permitir que jogadores Bedrock entrem sem uma conta Java. Sem Floodgate, eles precisarão autenticar com uma conta Java. Em servidores com <code>online-mode=false</code>, o Geyser pode usar autenticação <code>offline</code> sem Floodgate, mas esse modo é inseguro e permite falsificação de nomes; use Floodgate quando quiser autenticação Bedrock própria.</p>\n          <small>O ProtoBot continua sendo um cliente Java; GeyserMC adapta as conexões dos jogadores Bedrock ao servidor Java, não transforma o bot em cliente Bedrock.</small>\n        </aside>\n\n        <div class=\"grid-two\">\n          <article class=\"panel\">\n            <div class=\"panel-heading\"><div><span class=\"eyebrow\">CONEXÃO</span><h3>Servidor Minecraft</h3></div><span class=\"tag\">Java</span></div>\n            <div class=\"detail-row\"><span>Endereço</span><strong id=\"serverAddress\">127.0.0.1:25565</strong></div>\n            <div class=\"detail-row\"><span>Nome do bot</span><strong id=\"botName\">OllamaBot</strong></div>\n            <div class=\"detail-row\"><span>Autenticação</span><strong id=\"authMode\">Offline</strong></div>\n            <button class=\"button button-secondary full\" data-go=\"settings\">Editar conexão</button>\n          </article>\n          <article class=\"panel\">\n            <div class=\"panel-heading\"><div><span class=\"eyebrow\">INTELIGÊNCIA ARTIFICIAL</span><h3>Modelo local</h3></div><span class=\"tag tag-green\">Offline</span></div>\n            <div class=\"model-name\">Gemma 3 1B Instruct</div>\n            <p class=\"muted\">GGUF Q4_K_M · Execução local via llama.cpp</p>\n            <div class=\"detail-row\"><span>Temperatura</span><strong id=\"temperatureValue\">0.7</strong></div>\n            <div class=\"detail-row\"><span>Download inicial</span><strong>~806 MB</strong></div>\n          </article>\n        </div>\n\n        <article class=\"panel controls-panel\">\n          <div><span class=\"eyebrow\">CONTROLE</span><h3>Gerenciar bot</h3><p class=\"muted\">Os controles são aplicados ao processo do bot.</p></div>\n          <div class=\"control-buttons\">\n            <button class=\"button button-primary\" id=\"startButton\">▶ Iniciar bot</button>\n            <button class=\"button button-secondary\" id=\"pauseButton\" disabled>Ⅱ Pausar</button>\n            <button class=\"button button-danger\" id=\"stopButton\" disabled>■ Encerrar</button>\n          </div>\n        </article>\n\n        <article class=\"panel console-panel\">\n          <div class=\"panel-heading\"><div><span class=\"eyebrow\">ATIVIDADE RECENTE</span><h3>Console</h3></div><button class=\"text-button\" data-go=\"console\">Abrir console →</button></div>\n          <pre class=\"log-preview\" id=\"dashboardLogs\">Aguardando inicialização...</pre>\n        </article>\n      </section>\n\n      <section class=\"page\" id=\"page-settings\">\n        <div class=\"section-intro\"><span class=\"eyebrow\">PERSONALIZAÇÃO</span><h2>Configurações</h2><p>Defina como o ProtoBot se conecta e como a IA responde.</p></div>\n        <article class=\"panel form-panel\">\n          <div class=\"panel-heading\"><div><span class=\"eyebrow\">MINECRAFT JAVA</span><h3>Servidor</h3></div></div>\n          <div class=\"form-grid\">\n            <label class=\"field field-wide\">Endereço do servidor<input id=\"hostInput\" type=\"text\" placeholder=\"play.exemplo.com\"></label>\n            <label class=\"field\">Porta<input id=\"portInput\" type=\"number\" min=\"1\" max=\"65535\"></label>\n            <label class=\"field\">Nome do bot<input id=\"usernameInput\" type=\"text\" maxlength=\"16\"></label>\n            <label class=\"field\">Autenticação<select id=\"authInput\"><option value=\"offline\">Offline</option><option value=\"microsoft\">Microsoft</option></select></label>\n            <label class=\"field\">Versão do Minecraft<input id=\"versionInput\" type=\"text\" placeholder=\"26.2\"></label>\n          </div>\n        </article>\n        <article class=\"panel form-panel\">\n          <div class=\"panel-heading\"><div><span class=\"eyebrow\">MODELO LOCAL</span><h3>Inteligência artificial</h3></div><span class=\"tag tag-green\">Gemma 3 1B</span></div>\n          <div class=\"form-grid\">\n            <label class=\"field field-wide\">Modelo<input type=\"text\" value=\"Gemma 3 1B Instruct — GGUF Q4_K_M\" disabled></label>\n            <label class=\"field\">Temperatura <output id=\"temperatureOutput\">0.7</output><input id=\"temperatureInput\" type=\"range\" min=\"0\" max=\"2\" step=\"0.1\"></label>\n          </div>\n          <p class=\"hint\">O modelo é baixado automaticamente na primeira execução. Depois disso, a inferência funciona sem internet.</p>\n        </article>\n        <article class=\"panel form-panel\">\n          <div class=\"panel-heading\"><div><span class=\"eyebrow\">COMPORTAMENTO</span><h3>Chat</h3></div></div>\n          <label class=\"check-field\"><input id=\"mentionInput\" type=\"checkbox\"><span>Responder somente quando mencionarem o nome do bot</span></label>\n        </article>\n        <div class=\"form-actions\"><button class=\"button button-primary\" id=\"saveButton\">Salvar configurações</button><span id=\"saveFeedback\" class=\"muted\"></span></div>\n      </section>\n\n      <section class=\"page\" id=\"page-console\">\n        <div class=\"section-intro\"><span class=\"eyebrow\">DIAGNÓSTICO</span><h2>Console</h2><p>Mensagens do bot, conexão e execução da inteligência artificial.</p></div>\n        <article class=\"panel console-full-panel\">\n          <div class=\"panel-heading\"><div><span class=\"eyebrow\">LOG EM TEMPO REAL</span><h3>Registros</h3></div><button class=\"button button-secondary button-small\" id=\"clearLogsButton\">Limpar logs</button></div>\n          <pre id=\"fullLogs\" class=\"full-logs\"></pre>\n        </article>\n        <div class=\"danger-zone\"><div><strong>Encerrar aplicativo</strong><p>Fecha o ProtoBot e encerra o processo do bot.</p></div><button class=\"button button-danger\" id=\"forceQuitButton\">Forçar fechar</button></div>\n      </section>\n\n      <footer class=\"app-footer\"><span>ProtoBot · Interface multiplataforma</span><span>O bot utiliza o protocolo Minecraft Java.</span></footer>\n    </main>\n  </div>\n  <script>\n    (function () {\n      const queue = [];\n      window.protoNative = {\n        invoke: function (method, args) {\n          queue.push({method: method, args: Array.isArray(args) ? args : []});\n        }\n      };\n      window.__protoDrainCommands = function () {\n        return JSON.stringify(queue.splice(0, queue.length));\n      };\n      window.__protoReceive = function (event) {\n        document.dispatchEvent(new CustomEvent(\"proto-event\", {detail: event}));\n      };\n    })();\n  </script>\n</body>\n</html>",
"style.css": ":root{font-family:system-ui,Arial,sans-serif;color:#edf2f7;background:#0c1016;font-synthesis:none;text-rendering:optimizeLegibility;--bg:#0c1016;--panel:#141b24;--panel2:#192330;--line:#273342;--muted:#8d9aaa;--green:#7cdb8a;--green2:#b1f2a9;--red:#ff7777}\n*{box-sizing:border-box}body{margin:0;min-width:320px;background:radial-gradient(ellipse at 80% -10%,#1c2b32 0,transparent 42%),var(--bg)}button,input,select{font:inherit}.app-shell{display:flex;min-height:100vh}.sidebar{width:230px;flex-shrink:0;background:#10161e;border-right:1px solid var(--line);padding:26px 16px;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:12px;padding:0 9px 34px}.brand-mark,.welcome-orb{display:grid;place-items:center;background:linear-gradient(145deg,#9aeaa0,#3b9f70);color:#102018;font-family:system-ui;font-weight:700}.brand-mark{width:40px;height:40px;border-radius:13px;font-size:23px}.brand strong{display:block;font:700 18px system-ui}.brand small{color:var(--muted);font-size:11px;letter-spacing:1.4px;text-transform:uppercase}.nav{display:grid;gap:7px}.nav-item{border:0;background:transparent;color:#aab5c2;text-align:left;padding:12px 13px;border-radius:10px;cursor:pointer;font-weight:600}.nav-item:hover,.nav-item.active{background:#1d2b31;color:var(--green2)}.nav-icon{display:inline-block;width:27px;font-size:17px}.sidebar-footer{margin-top:auto;display:flex;align-items:center;gap:9px;color:var(--muted);font-size:12px;padding:15px 8px}.connection-dot,.status-dot{width:8px;height:8px;border-radius:50%;background:#687482}.connection-dot.running,.status-dot.running{background:var(--green);box-shadow:0 0 12px #7cdb8a88}.main{width:min(1120px,100%);margin:0 auto;padding:30px 42px 20px}.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:27px}.eyebrow{display:block;color:#7fae91;font-size:10px;font-weight:700;letter-spacing:1.7px}.topbar h1,.section-intro h2{font:600 27px system-ui;margin:5px 0 0}.top-status{display:flex;align-items:center;gap:9px;background:#151e28;border:1px solid var(--line);border-radius:30px;padding:9px 14px;color:#b9c4d0;font-size:12px}.page{display:none}.page.active{display:block}.welcome-card{position:relative;overflow:hidden;display:flex;justify-content:space-between;align-items:center;min-height:180px;padding:30px 34px;border:1px solid #355044;border-radius:18px;background:linear-gradient(110deg,#1b302b,#17252b 65%,#1c2a34);margin-bottom:18px}.welcome-card h2{font:600 25px system-ui;margin:10px 0}.welcome-card p,.section-intro p{color:#aab8c4;max-width:570px;line-height:1.6;margin:0;font-size:13px}.welcome-orb{width:105px;height:105px;border-radius:34px;transform:rotate(12deg);font-size:54px;box-shadow:0 0 60px #7cdb8a30;margin-right:28px}.grid-two{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-bottom:18px}.panel{background:linear-gradient(145deg,#161f29,#131a23);border:1px solid var(--line);border-radius:15px;padding:21px;margin-bottom:18px}.grid-two .panel{margin:0}.panel-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.panel h3{font:600 17px system-ui;margin:5px 0 0}.tag{background:#26313e;color:#b9c7d5;border:1px solid #354252;border-radius:30px;padding:5px 10px;font-size:10px;font-weight:700}.tag-green{background:#1e3529;border-color:#31583c;color:var(--green2)}.detail-row{display:flex;justify-content:space-between;gap:15px;padding:10px 0;border-bottom:1px solid #222d39;font-size:12px;color:var(--muted)}.detail-row strong{color:#e4ebf1;font-weight:600;text-align:right}.button{border:1px solid transparent;border-radius:9px;padding:11px 15px;font-size:12px;font-weight:700;cursor:pointer;transition:transform .15s,filter .15s}.button:hover:not(:disabled){filter:brightness(1.12);transform:translateY(-1px)}.button:disabled{opacity:.38;cursor:not-allowed}.button-primary{background:var(--green);color:#102018}.button-secondary{background:#202b38;border-color:#344253;color:#dce5ed}.button-danger{background:#3a2227;border-color:#65333a;color:#ffaaaa}.button-small{padding:8px 12px}.full{width:100%;margin-top:16px}.model-name{font:600 16px system-ui;margin:5px 0}.muted{color:var(--muted);font-size:12px;line-height:1.55}.controls-panel{display:flex;align-items:center;justify-content:space-between;gap:20px}.controls-panel h3{margin:5px 0}.controls-panel p{margin:5px 0 0}.control-buttons{display:flex;gap:8px;flex-wrap:wrap}.log-preview,.full-logs{background:#0b1118;border:1px solid #202c39;border-radius:10px;color:#a9c7b0;font:11px/1.65 \"Consolas\",monospace;white-space:pre-wrap;overflow:auto;margin:0}.log-preview{height:105px;padding:12px}.text-button{border:0;background:none;color:var(--green2);font-size:11px;font-weight:700;cursor:pointer}.section-intro{margin:4px 0 22px}.section-intro h2{font-size:25px;margin:6px 0}.section-intro p{font-size:12px}.form-panel{padding:24px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.field{display:grid;gap:8px;color:#aebbc8;font-size:12px;font-weight:600}.field-wide{grid-column:1/-1}.field input,.field select{width:100%;border:1px solid #344252;border-radius:8px;background:#0e151d;color:#edf2f7;padding:12px;outline:none}.field input:focus,.field select:focus{border-color:#78c98a}.field input:disabled{color:#718092}.field input[type=range]{padding:0;accent-color:var(--green)}.field output{display:inline;color:var(--green2)}.hint{color:var(--muted);font-size:11px;margin:16px 0 0}.check-field{display:flex;align-items:center;gap:10px;color:#c2ccd6;font-size:12px}.check-field input{accent-color:var(--green);width:16px;height:16px}.form-actions{display:flex;align-items:center;gap:14px;margin-bottom:24px}.full-logs{height:420px;padding:16px}.danger-zone{display:flex;align-items:center;justify-content:space-between;padding:18px 20px;border:1px solid #503139;background:#21181e;border-radius:12px;margin:18px 0}.danger-zone strong{font-size:13px}.danger-zone p{font-size:11px;color:var(--muted);margin:5px 0 0}.app-footer{display:flex;justify-content:space-between;gap:15px;border-top:1px solid var(--line);padding-top:16px;margin-top:15px;color:#657384;font-size:10px}\n@media(max-width:760px){.sidebar{width:65px;padding:18px 8px}.brand{padding:0 4px 30px}.brand>div:last-child,.nav-item:not(.active){font-size:0}.brand-mark{width:43px}.nav-item{padding:12px 9px;font-size:0}.nav-icon{font-size:18px;width:auto}.sidebar-footer{font-size:0;padding:10px 8px}.main{padding:22px 18px}.grid-two{grid-template-columns:1fr}.controls-panel{align-items:flex-start;flex-direction:column}.welcome-card{padding:24px}.welcome-orb{width:68px;height:68px;font-size:35px;margin:0}.welcome-card h2{font-size:20px}.form-grid{grid-template-columns:1fr}.field-wide{grid-column:auto}.app-footer{flex-direction:column}.topbar h1{font-size:23px}}\n@media(max-width:430px){.top-status{font-size:0;padding:10px}.top-status .status-dot{width:9px;height:9px}.control-buttons{width:100%}.control-buttons .button{flex:1}.panel{padding:17px}.welcome-orb{display:none}}\n.compatibility-notice{border:1px solid #66552f;background:#282318;border-radius:13px;padding:17px 20px;margin:0 0 18px;color:#e9dfc7;font-size:12px;line-height:1.65}.compatibility-notice strong{color:#ffe0a0}.compatibility-notice p{margin:7px 0;color:#d0c5ae}.compatibility-notice a{color:#9fd7ff}.compatibility-notice code{background:#171b20;padding:2px 5px;border-radius:4px}.compatibility-notice small{display:block;color:#b6aa92;margin-top:9px}\n",
"app.js": "(function () {\n  \"use strict\";\n  let logs = [];\n  let currentState = {running:false,paused:false};\n\n  const byId = id => document.getElementById(id);\n  const call = (name, ...args) => {\n    if (!window.protoNative || typeof window.protoNative.invoke !== \"function\") {\n      appendLog(\"[UI] A comunicação com o aplicativo ainda não está disponível.\");\n      return;\n    }\n    window.protoNative.invoke(name,args);\n  };\n\n  function appendLog(line) {\n    const text = String(line || \"\");\n    if (!text) return;\n    logs.push(text);\n    if (logs.length > 1200) logs = logs.slice(-1200);\n    const joined = logs.join(\"\\n\");\n    const full = byId(\"fullLogs\");\n    const preview = byId(\"dashboardLogs\");\n    if (full) { full.textContent = joined; full.scrollTop = full.scrollHeight; }\n    if (preview) {\n      preview.textContent = logs.slice(-7).join(\"\\n\") || \"Aguardando inicialização...\";\n      preview.scrollTop = preview.scrollHeight;\n    }\n  }\n\n  function setState(running, paused) {\n    currentState = {running:!!running,paused:!!paused};\n    const label = !running ? \"Parado\" : paused ? \"Pausado\" : \"Em execução\";\n    [\"statusText\",\"sideStatus\"].forEach(id => {\n      if (byId(id)) byId(id).textContent = id === \"sideStatus\" ? (running ? label : \"Bot desconectado\") : label;\n    });\n    [\"statusDot\",\"sideDot\"].forEach(id => {\n      if (byId(id)) byId(id).classList.toggle(\"running\",!!running && !paused);\n    });\n    if (byId(\"startButton\")) byId(\"startButton\").disabled = !!running;\n    if (byId(\"pauseButton\")) {\n      byId(\"pauseButton\").disabled = !running;\n      byId(\"pauseButton\").textContent = paused ? \"▶ Retomar\" : \"Ⅱ Pausar\";\n    }\n    if (byId(\"stopButton\")) byId(\"stopButton\").disabled = !running;\n  }\n\n  function fillConfig(config) {\n    const mc = config.minecraft || {};\n    const ai = config.ai || {};\n    const behavior = config.behavior || {};\n    byId(\"hostInput\").value = mc.host || \"127.0.0.1\";\n    byId(\"portInput\").value = mc.port || 25565;\n    byId(\"usernameInput\").value = mc.username || \"ProtoBot\";\n    byId(\"authInput\").value = mc.auth || \"offline\";\n    byId(\"versionInput\").value = mc.version || \"26.2\";\n    byId(\"temperatureInput\").value = ai.temperature ?? 0.7;\n    byId(\"temperatureOutput\").textContent = Number(byId(\"temperatureInput\").value).toFixed(1);\n    byId(\"mentionInput\").checked = !!behavior.respond_only_when_mentioned;\n    byId(\"serverAddress\").textContent = (mc.host || \"127.0.0.1\") + \":\" + (mc.port || 25565);\n    byId(\"botName\").textContent = mc.username || \"ProtoBot\";\n    byId(\"authMode\").textContent = mc.auth === \"microsoft\" ? \"Microsoft\" : \"Offline\";\n    byId(\"temperatureValue\").textContent = Number(ai.temperature ?? 0.7).toFixed(1);\n  }\n\n  function collectConfig() {\n    return JSON.stringify({\n      minecraft:{\n        host:byId(\"hostInput\").value.trim(),\n        port:Number(byId(\"portInput\").value || 25565),\n        username:byId(\"usernameInput\").value.trim(),\n        auth:byId(\"authInput\").value,\n        version:byId(\"versionInput\").value.trim() || \"26.2\"\n      },\n      ai:{model:\"gemma-3-1b-it-Q4_K_M.gguf\",temperature:Number(byId(\"temperatureInput\").value)},\n      behavior:{respond_only_when_mentioned:byId(\"mentionInput\").checked}\n    });\n  }\n\n  function showPage(name) {\n    document.querySelectorAll(\".page\").forEach(page => page.classList.toggle(\"active\",page.id === \"page-\" + name));\n    document.querySelectorAll(\".nav-item\").forEach(item => item.classList.toggle(\"active\",item.dataset.section === name));\n    const titles = {dashboard:\"Visão geral\",settings:\"Configurações\",console:\"Console\"};\n    byId(\"pageTitle\").textContent = titles[name] || \"ProtoBot\";\n  }\n\n  function receiveEvent(event) {\n    if (!event || typeof event !== \"object\") return;\n    if (event.type === \"log\") appendLog(event.text);\n    else if (event.type === \"clearLogs\") { logs = []; appendLog(\"Logs limpos.\"); }\n    else if (event.type === \"state\") setState(event.running,event.paused);\n    else if (event.type === \"config\") {\n      try { fillConfig(typeof event.value === \"string\" ? JSON.parse(event.value) : event.value); }\n      catch(e) { appendLog(\"[UI] Erro ao carregar configurações: \" + e); }\n    }\n  }\n\n  function init() {\n    document.querySelectorAll(\".nav-item\").forEach(item => item.addEventListener(\"click\",() => showPage(item.dataset.section)));\n    document.querySelectorAll(\"[data-go]\").forEach(item => item.addEventListener(\"click\",() => showPage(item.dataset.go)));\n    byId(\"startButton\").addEventListener(\"click\",() => { call(\"saveConfig\",collectConfig()); call(\"startBot\"); });\n    byId(\"pauseButton\").addEventListener(\"click\",() => call(\"togglePause\"));\n    byId(\"stopButton\").addEventListener(\"click\",() => call(\"stopBot\"));\n    byId(\"saveButton\").addEventListener(\"click\",() => call(\"saveConfig\",collectConfig()));\n    byId(\"clearLogsButton\").addEventListener(\"click\",() => call(\"clearLogs\"));\n    byId(\"forceQuitButton\").addEventListener(\"click\",() => call(\"forceQuit\"));\n    byId(\"temperatureInput\").addEventListener(\"input\",() => byId(\"temperatureOutput\").textContent = Number(byId(\"temperatureInput\").value).toFixed(1));\n    document.addEventListener(\"proto-event\",event => receiveEvent(event.detail));\n    call(\"requestInitialData\");\n  }\n\n  if (document.readyState === \"loading\") document.addEventListener(\"DOMContentLoaded\",init);\n  else init();\n})();"
}

def install_interface_files(destination: Path) -> Path:
    destination = Path(destination) / "interface"
    destination.mkdir(parents=True, exist_ok=True)
    for filename, content in FILES.items():
        target = destination / filename
        if not target.exists() or target.read_text(encoding="utf-8") != content:
            target.write_text(content, encoding="utf-8")
    return destination
